import { Outlet } from "react-router";
import MainNavigation from '../components/Navigation'
import cssClasses  from './Root.module.css'

function RootLayout()
{
    return (
        <>
            <MainNavigation />
            <main className={cssClasses}>
                <Outlet />
            </main>
        </> 
        ); 
    
}

export default RootLayout;
